begin;drop policy "Posts readable" on public.posts;create policy "Posts public read" on public.posts for select to anon using(not hidden);create policy "Posts member read" on public.posts for select to authenticated using(not hidden or author_id=(select auth.uid()) or public.is_editor());drop policy "Comments readable" on public.comments;create policy "Comments public read" on public.comments for select to anon using(not hidden and exists(select 1 from public.posts where id=post_id));create policy "Comments member read" on public.comments for select to authenticated using((not hidden or author_id=(select auth.uid()) or public.is_editor()) and exists(select 1 from public.posts where id=post_id));commit;
